args.content:
import { cookies, headers } from 'next/headers';

export default async function UserPreferences() {
  const cookieStore = await cookies();
  const headersList = await headers();

  const theme = cookieStore.get('theme')?.value || 'light';
  const acceptLanguage = headersList.get('accept-language') || 'en-US';

  return (
    <div className="preferences-container">
      <div className="preference-item">
        <strong>Current Theme:</strong> <span>{theme}</span>
      </div>
      <div className="preference-item">
        <strong>Preferred Language:</strong> <span>{acceptLanguage}</span>
      </div>
    </div>
  );
}

